app.get('/orders', async (req, res, next) => {
  try {
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);
    const params = [limit + 1];
    let where = '';

    if (req.query.cursor) {
      let cursor;
      try {
        cursor = JSON.parse(Buffer.from(req.query.cursor, 'base64url').toString());
      } catch {}
      if (!Array.isArray(cursor) || cursor.length !== 2) {
        return res.status(400).json({ error: 'Invalid cursor' });
      }
      params.push(cursor[0], cursor[1]);
      where = 'WHERE (created_at, id) < ($2::timestamptz, $3)';
    }

    // created_at is read as text because a JS Date drops microseconds,
    // which would make the cursor skip or repeat rows.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      params
    );

    // One extra row is fetched to tell whether another page exists.
    const hasMore = rows.length > limit;
    const page = hasMore ? rows.slice(0, limit) : rows;
    const last = page[page.length - 1];
    const nextCursor = hasMore
      ? Buffer.from(JSON.stringify([last.cursor_ts, last.id])).toString('base64url')
      : null;

    res.json({
      orders: page.map(({ cursor_ts, ...order }) => order),
      nextCursor,
    });
  } catch (err) {
    next(err);
  }
});
```

This assumes `pool` is your `pg` Pool, and it needs an index on `orders (created_at DESC, id DESC)` to stay fast.

