package main

import (
	"flag"
	"fmt"
	"os"
)

func main() {
	verbose := flag.Bool("verbose", false, "print extra output")
	output := flag.String("output", "out.txt", "file to write results to")
	count := flag.Int("count", 1, "number of times to run")

	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), "Usage: %s [flags] <input>...\n\nFlags:\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()

	inputs := flag.Args()
	if len(inputs) == 0 {
		flag.Usage()
		os.Exit(2)
	}

	fmt.Println(*verbose, *output, *count, inputs)
}
```

This uses the standard library's `flag` package, which already covers all four requirements, rather than a hand-written parser. `-h` prints the generated help, and flags must come before the positional arguments because parsing stops at the first one.

```ts
type Job<T> = () => Promise<T>;

export class JobQueue {
  private pending: Array<() => Promise<void>> = [];
  private running = 0;
  private idleWaiters: Array<() => void> = [];

  constructor(private concurrency: number, private maxRetries = 3) {}

  /** Queues a job; the returned promise settles with its final outcome. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        for (let attempt = 0; ; attempt++) {
          try {
            return resolve(await job());
          } catch (err) {
            if (attempt >= this.maxRetries) return reject(err);
          }
        }
      });
      this.next();
    });
  }

  /** Resolves once nothing is queued or running. */
  onIdle(): Promise<void> {
    if (this.running === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const run = this.pending.shift()!;
      this.running++;
      run().finally(() => {
        this.running--;
        this.next();
      });
    }
    if (this.running === 0 && this.pending.length === 0) {
      for (const resolve of this.idleWaiters.splice(0)) resolve();
    }
  }
}
```

Use it as `const queue = new JobQueue(4); queue.add(() => doWork()); await queue.onIdle();`. The promise from `add` rejects once a job has failed its first run and all three retries, so catch it or Node will report an unhandled rejection. Retries run immediately, with no delay between attempts.
